/* From Uiverse.io by Kagamiie  - Tags: simple, card, about me, profilecard */
.__UIV_SCOPE__ .project-info {
  padding: 100px 40px;
  display: flex;
  flex-direction: column;
  gap: 20px;
  position: relative;
  top: -50px;
}

.__UIV_SCOPE__ .project-title {
  font-weight: 500;
  font-size: 1.5em;
  overflow: hidden;
  text-overflow: ellipsis;
  white-space: nowrap;
  color: black;
}

.__UIV_SCOPE__ .lighter {
  font-size: 0.9em;
}

.__UIV_SCOPE__ .flex {
  display: flex;
  justify-content: space-between;
  align-items: center;
}

.__UIV_SCOPE__ .tag {
  font-weight: lighter;
  color: grey;
}

/*DELETE THIS TWO LINE*/
.__UIV_SCOPE__ .delete {
  background-color: #b2b2fd;
}

.__UIV_SCOPE__ .card-img div {
  width: 90%;
}
/*IF USING IMAGES*/

.__UIV_SCOPE__ .card {
  background-color: white;
  color: black;
  width: 300px;
  max-height: 330px;
  border-radius: 8px;
  box-shadow: rgba(50, 50, 93, 0.25) 0px 50px 100px -20px,
    rgba(0, 0, 0, 0.3) 0px 30px 60px -30px;
}

.__UIV_SCOPE__ .card-img {
  position: relative;
  top: -20px;
  height: 100px;
  display: flex;
  justify-content: center;
}

/* Change the .card-img div to .card-img img to use img*/
.__UIV_SCOPE__ .card-img a,
.__UIV_SCOPE__ .card-img div {
  height: 150px;
  width: 90%;
  /* Change this width here to change the width of the color/image */
  object-fit: cover;
  border-radius: 8px;
  box-shadow: rgba(149, 157, 165, 0.2) 0px 8px 24px;
}

.__UIV_SCOPE__ .card-imgs {
  transition: all 0.5s;
}
